} from "firebase/firestore";
import { ALL_MATCHES, TEAM_FLAGS } from "../data/matches";
import { format, startOfWeek, endOfWeek, addWeeks, subWeeks, isWithinInterval, parseISO } from "date-fns";
import { ChevronLeft, ChevronRight, MapPin, Clock, CheckCircle2, Lock } from "lucide-react";

function isPredictionLocked(matchDate) {
  const cutoff = new Date(matchDate).getTime() - 5 * 60 * 1000; // 5 min before
  return Date.now() >= cutoff;
}

function getMatchStatus(matchDate, result) {
  const now = Date.now();
  const start = new Date(matchDate).getTime();
  if (result) return "finished";
  if (now >= start) return "live";
  if (isPredictionLocked(matchDate)) return "locked";
  return "upcoming";
}

function Countdown({ matchDate }) {
  const [timeLeft, setTimeLeft] = useState("");

  useEffect(() => {
    const update = () => {
      const diff = new Date(matchDate).getTime() - Date.now();
      if (diff <= 0) { setTimeLeft(""); return; }
      const h = Math.floor(diff / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      const s = Math.floor((diff % 60000) / 1000);
      if (h > 0) setTimeLeft(`${h}h ${m}m`);
      else if (m > 0) setTimeLeft(`${m}m ${s}s`);
      else setTimeLeft(`${s}s`);
    };
    update();
    const id = setInterval(update, 1000);
    return () => clearInterval(id);
  }, [matchDate]);

  if (!timeLeft) return null;
  const locksSoon = new Date(matchDate).getTime() - Date.now() < 10 * 60 * 1000;

  return (
    <span className={`text-xs font-mono font-semibold ${locksSoon ? "text-orange-400 animate-pulse" : "text-gray-400 dark:text-gray-500"}`}>
      {locksSoon ? `🔒 Locks in ${timeLeft}` : `Starts in ${timeLeft}`}
    </span>
  );
}

function MatchCard({ match, userPrediction, onPredict, allPredictionsCount }) {
  const status = getMatchStatus(match.date, match.result);
  const locked = isPredictionLocked(match.date);
  const isFinished = status === "finished";

  const homeWon = match.result === "home";
  const awayWon = match.result === "away";
  const isDraw = match.result === "draw";

  const homeFlag = TEAM_FLAGS[match.home] || "🏳️";
  const awayFlag = TEAM_FLAGS[match.away] || "🏳️";

  return (
    <div className={`rounded-2xl border transition-all duration-200 overflow-hidden
      ${isFinished
        ? "bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-800"
        : status === "live"
        ? "bg-white dark:bg-gray-900 border-green-400/50 shadow-green-400/10 shadow-lg"
        : "bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-800 hover:border-fifa-gold/40 hover:shadow-md"
      }`}
    >
      {/* Stage badge */}
      <div className="px-4 pt-3 pb-1 flex items-center justify-between">
        <span className={`text-xs font-semibold uppercase tracking-wider px-2 py-0.5 rounded-full
          ${match.group
            ? "bg-fifa-blue/10 dark:bg-fifa-blue/30 text-fifa-blue dark:text-blue-300"
            : "bg-purple-100 dark:bg-purple-900/30 text-purple-700 dark:text-purple-300"
          }`}>
          {match.stage}
        </span>
        <div className="flex items-center gap-2">
          {status === "live" && (
            <span className="flex items-center gap-1 text-green-400 text-xs font-bold">
              <span className="w-2 h-2 rounded-full bg-green-400 animate-pulse" />
              LIVE
            </span>
          )}
          {status === "upcoming" && <Countdown matchDate={match.date} />}
          {status === "locked" && !isFinished && (
            <span className="flex items-center gap-1 text-orange-400 text-xs font-semibold">
              <Lock size={12} /> Locked
            </span>
          )}
        </div>
      </div>

      {/* Teams */}
      <div className="px-4 py-3 grid grid-cols-3 items-center gap-2">
        {/* Home */}
        <div className={`flex flex-col items-center gap-1 p-2 rounded-xl transition
          ${userPrediction === "home" ? "bg-fifa-gold/15 ring-2 ring-fifa-gold" : ""}
          ${isFinished && homeWon ? "bg-green-500/10 ring-1 ring-green-500/40" : ""}
        `}>
          <span className="text-3xl">{homeFlag}</span>
          <span className="text-sm font-bold text-center leading-tight text-gray-900 dark:text-white">
            {match.home}
          </span>
          {isFinished && homeWon && (
            <span className="text-xs text-green-500 font-semibold">Won</span>
          )}
        </div>

        {/* VS / Result */}
        <div className="flex flex-col items-center gap-1">
          {isFinished ? (
            <div className="text-center">
              {isDraw ? (
                <span className="text-sm font-bold text-gray-400">DRAW</span>
              ) : (
                <span className="text-xs text-gray-500 dark:text-gray-400 font-medium">FT</span>
              )}
            </div>
          ) : (
            <span className="text-gray-400 dark:text-gray-600 font-bold text-lg">VS</span>
          )}
          <div className="flex flex-col items-center">
            <span className="text-xs text-gray-500 dark:text-gray-500 flex items-center gap-1">
              <Clock size={10} />
              {format(parseISO(match.date), "HH:mm")}
            </span>
            <span className="text-xs text-gray-400 dark:text-gray-600">
              {format(parseISO(match.date), "MMM d")}
            </span>
          </div>
        </div>

        {/* Away */}
        <div className={`flex flex-col items-center gap-1 p-2 rounded-xl transition
          ${userPrediction === "away" ? "bg-fifa-gold/15 ring-2 ring-fifa-gold" : ""}
          ${isFinished && awayWon ? "bg-green-500/10 ring-1 ring-green-500/40" : ""}
        `}>
          <span className="text-3xl">{awayFlag}</span>
          <span className="text-sm font-bold text-center leading-tight text-gray-900 dark:text-white">
            {match.away}
          </span>
          {isFinished && awayWon && (
            <span className="text-xs text-green-500 font-semibold">Won</span>
          )}
        </div>
      </div>

      {/* Venue */}
      <div className="px-4 pb-2 flex items-center gap-1 text-xs text-gray-400 dark:text-gray-600">
        <MapPin size={11} />
        <span className="truncate">{match.venue}</span>
      </div>

      {/* Prediction buttons */}
      <div className="px-4 pb-4">
        {match.home === "TBD" || match.away === "TBD" ? (
          <div className="text-center py-2 text-xs text-gray-400 dark:text-gray-600 italic">
            Teams to be determined
          </div>
        ) : locked ? (
          <div className={`flex items-center justify-center gap-2 py-2 rounded-xl text-sm font-medium
            ${userPrediction
              ? "bg-fifa-gold/10 text-fifa-gold border border-fifa-gold/30"
              : "bg-gray-100 dark:bg-gray-800 text-gray-400 dark:text-gray-600"
            }`}>
            {userPrediction ? (
              <>
                <CheckCircle2 size={16} />
                Your pick: {userPrediction === "home" ? match.home : match.away}
                {isFinished && (
                  <span className={`ml-1 text-xs font-bold ${
                    (userPrediction === "home" && homeWon) || (userPrediction === "away" && awayWon)
                      ? "text-green-400" : isDraw ? "text-gray-400" : "text-red-400"
                  }`}>
                    {(userPrediction === "home" && homeWon) || (userPrediction === "away" && awayWon)
                      ? "✓ +1 pt"
                      : isDraw ? "— Draw"
                      : "✗ No point"}
                  </span>
                )}
              </>
            ) : (
              <>
                <Lock size={16} />
                No prediction made
              </>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-2">
            <button
              onClick={() => onPredict(match.id, "home")}
              className={`py-2.5 px-3 rounded-xl text-sm font-bold transition-all duration-150
                ${userPrediction === "home"
                  ? "bg-fifa-gold text-fifa-navy shadow-lg shadow-fifa-gold/20"
                  : "bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 hover:bg-fifa-gold/20 hover:text-fifa-gold"
                }`}
            >
              {homeFlag} {match.home}
            </button>
            <button
              onClick={() => onPredict(match.id, "away")}
              className={`py-2.5 px-3 rounded-xl text-sm font-bold transition-all duration-150
                ${userPrediction === "away"
                  ? "bg-fifa-gold text-fifa-navy shadow-lg shadow-fifa-gold/20"
                  : "bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 hover:bg-fifa-gold/20 hover:text-fifa-gold"
                }`}
            >
              {awayFlag} {match.away}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default function Fixtures() {
  const { user } = useAuth();
  const [weekOffset, setWeekOffset] = useState(0);
  const [predictions, setPredictions] = useState({});
  const [firestoreMatches, setFirestoreMatches] = useState({});

  // Current week window
  const baseDate = new Date("2026-06-11");
  const weekStart = startOfWeek(addWeeks(baseDate, weekOffset), { weekStartsOn: 4 }); // Thu
  const weekEnd = endOfWeek(addWeeks(baseDate, weekOffset), { weekStartsOn: 4 });

  // Matches for this week
  const weekMatches = ALL_MATCHES.filter((m) => {
    const d = parseISO(m.date);
    return isWithinInterval(d, { start: weekStart, end: weekEnd });
  });

  // Load user predictions from Firestore (realtime)
  useEffect(() => {
    if (!user) return;
    const q = query(
      collection(db, "predictions"),
      where("userId", "==", user.uid)
    );
    const unsub = onSnapshot(q, (snap) => {
      const preds = {};
      snap.forEach((d) => {
        preds[d.data().matchId] = d.data().pick;
      });
      setPredictions(preds);
    });
    return unsub;
  }, [user]);

  // Load match results from Firestore (realtime)
  useEffect(() => {
    const unsub = onSnapshot(collection(db, "matches"), (snap) => {
      const results = {};
      snap.forEach((d) => { results[d.id] = d.data(); });
      setFirestoreMatches(results);
    });
    return unsub;
  }, []);

  const handlePredict = useCallback(async (matchId, pick) => {
    if (!user) return;
    if (isPredictionLocked(ALL_MATCHES.find((m) => m.id === matchId)?.date)) return;
    const predId = `${user.uid}_${matchId}`;
    await setDoc(doc(db, "predictions", predId), {
      userId: user.uid,
      matchId,
      pick,
      createdAt: Date.now(),
    });
  }, [user]);

  // Merge static match data with Firestore results
  const enrichedMatches = weekMatches.map((m) => ({
    ...m,
    ...(firestoreMatches[m.id] || {}),
  }));

  const groupedByDay = enrichedMatches.reduce((acc, m) => {
    const day = format(parseISO(m.date), "EEEE, MMMM d");
    if (!acc[day]) acc[day] = [];
    acc[day].push(m);
    return acc;
  }, {});

  return (
    <div>
      {/* Week nav */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Fixtures</h1>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            {format(weekStart, "MMM d")} – {format(weekEnd, "MMM d, yyyy")}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setWeekOffset((w) => w - 1)}
            className="p-2 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 hover:border-fifa-gold/50 transition"
          >
            <ChevronLeft size={18} />
          </button>
          <button
            onClick={() => setWeekOffset(0)}
            className="px-3 py-1.5 text-sm font-medium rounded-lg bg-fifa-blue dark:bg-fifa-gold text-white dark:text-fifa-navy hover:opacity-90 transition"
          >
            This Week
          </button>
          <button
            onClick={() => setWeekOffset((w) => w + 1)}
            className="p-2 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 hover:border-fifa-gold/50 transition"
          >
            <ChevronRight size={18} />
          </button>
        </div>
      </div>

      {weekMatches.length === 0 ? (
        <div className="text-center py-20 text-gray-400 dark:text-gray-600">
          <span className="text-5xl block mb-4">📅</span>
          <p className="text-lg font-medium">No matches this week</p>
          <p className="text-sm mt-1">Try navigating to a different week</p>
        </div>
      ) : (
        <div className="space-y-8">
          {Object.entries(groupedByDay).map(([day, matches]) => (
            <div key={day}>
              <h2 className="text-sm font-bold uppercase tracking-widest text-gray-500 dark:text-gray-400 mb-3 flex items-center gap-2">
                <span className="flex-1 h-px bg-gray-200 dark:bg-gray-800" />
                {day}
                <span className="flex-1 h-px bg-gray-200 dark:bg-gray-800" />
              </h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {matches.map((match) => (
                  <MatchCard
                    key={match.id}
                    match={match}
                    userPrediction={predictions[match.id]}
                    onPredict={handlePredict}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
